  def path_search(self, start, goal):
    open_set = []  # Set to store nodes to be explored
    closed_set = set()  # Set to store visited nodes
    start_node = {
        "state": start,
        "parent": None,
        "g": 0,
        "h": 0,
        "f": 0  # heuristic estimated cost to goal
    }
    open_set.append(start_node)  

    while open_set:
      current_node = min(open_set, key=lambda x: x["f"])
      open_set.remove(current_node)
      closed_set.add(current_node["state"])

      if current_node["state"] == goal:
        return self. reconstruct_path(current_node)

      for neighbor in self.graph[current_node["state"]]:
