            "state": neighbor,
            "parent": current_node,
            "g": current_node["g"] + 1,  # Assuming uniform cost
            "h": self.manhattan_distance(neighbor, goal),  # Calculate heuristic
            "f": current_node["g"] + neighbor_node["h"]  # Total estimated cost
        }
        if neighbor not in closed_set:
            open_set.append(neighbor_node)

    return None  # No path found

  def manhattan_distance(self, current, goal):
    return abs(current[0] - goal[0]) + abs(current[1] - goal[1])

  def reconstruct_path(self, node):
    path = []
    while node:
      path.append(node["state"])
      node = node["parent"]
    return path[::-1] 

